6	static void expect_erase(Halfedge_Mesh& mesh, Halfedge_Mesh::VertexRef vertex, Halfedge_Mesh const &after) {
7		size_t numVerts = mesh.vertices.size();
8		size_t numEdges = mesh.edges.size();
9		size_t numFaces = mesh.faces.size();
10	
11		// collect all vertices belonging to faces touching v
12		std::set<uint32_t> face_vert_ids;
13		Halfedge_Mesh::HalfedgeRef he = vertex->halfedge;
14		Halfedge_Mesh::HalfedgeRef heOrig = he;
15		do {
16			Halfedge_Mesh::HalfedgeRef tempOrig = he;
17			do {
18				face_vert_ids.insert(he->vertex->id);
19				he = he->next;
20			} while (he->next != tempOrig);
21			he = he->twin;
22		} while (he != heOrig);
23		face_vert_ids.erase(vertex->id);
24	
25		size_t vertDeg = vertex->degree();
26		uint32_t erased_id = vertex->id;
27	
28		if (auto ret = mesh.dissolve_vertex(vertex)) {
29			if (auto msg = mesh.validate()) {
30				throw Test::error("Invalid mesh: " + msg.value().second);
31			}
32			// check if input vertex is erased
33			std::set<uint32_t> vert_ids;
34			for (Halfedge_Mesh::VertexRef ve = mesh.vertices.begin(); ve != mesh.vertices.begin(); ve++) {
35				vert_ids.insert(ve->id);
36			}
37			if (vert_ids.find(erased_id) != vert_ids.end()) {
38				throw Test::error("Erase vertex did not erase the input vertex!");
39			}
40			// check if returned face contains vertices originally belonging to its one-ring
41			std::set<uint32_t> new_face_vert_ids;
42			Halfedge_Mesh::HalfedgeRef new_he = ret.value()->halfedge;
43			Halfedge_Mesh::HalfedgeRef new_he_orig = new_he;
44			do {
45				new_face_vert_ids.insert(new_he->vertex->id);
46				new_he = new_he->next;
47			} while (new_he != new_he_orig);
48			if (face_vert_ids != new_face_vert_ids) {
49				throw Test::error("Erase vertex did not return a face with correct vertices!");
50			}
51			// check for expected number of elements
52			if (numVerts - 1 != mesh.vertices.size()) {
53				throw Test::error("Erase vertex did not erase a vertex!");
54			}
55			if (numEdges - vertDeg != mesh.edges.size()) {
56				throw Test::error("Erase vertex did not erase an edge!");
57			}
58			if (numFaces - vertDeg + 1 != mesh.faces.size()) {
59				throw Test::error("Erase vertex did not erase a face!");
60			}
61			// check mesh shape:
62	        if (auto diff = Test::differs(mesh, after)) {
63			    throw Test::error("Result does not match expected: " + diff.value());
64		    }
65		} else {
66			throw Test::error("Erase vertex rejected operation!");
67		}
68	}
