6	static void expect_erase(Halfedge_Mesh& mesh, Halfedge_Mesh::EdgeRef edge, Halfedge_Mesh const &after) {
7		size_t numVerts = mesh.vertices.size();
8		size_t numEdges = mesh.edges.size();
9		size_t numFaces = mesh.faces.size();
10	
11		std::set<uint32_t> vert_ids;
12		Halfedge_Mesh::HalfedgeRef he = edge->halfedge;
13		Halfedge_Mesh::HalfedgeRef heOrig = he;
14		do {
15			vert_ids.insert(he->vertex->id);
16			he = he->next;
17		} while (he != heOrig);
18		he = heOrig->twin;
19		heOrig = heOrig->twin;
20		do {
21			vert_ids.insert(he->vertex->id);
22			he = he->next;
23		} while (he != heOrig);
24	
25		uint32_t erased_id = edge->id;
26	
27		if (auto ret = mesh.dissolve_edge(edge)) {
28			if (auto msg = mesh.validate()) {
29				throw Test::error("Invalid mesh: " + msg.value().second);
30			}
31			// check if input edge is erased
32			std::set<uint32_t> edge_ids;
33			for (Halfedge_Mesh::EdgeRef ed = mesh.edges.begin(); ed != mesh.edges.end(); ed++) {
34				edge_ids.insert(ed->id);
35			}
36			if (edge_ids.find(erased_id) != edge_ids.end()) {
37				throw Test::error("Erase edge did not erase the input edge!");
38			}
39			// check if returned face contains vertices originally belonging to two faces touching the edge
40			std::set<uint32_t> new_vert_ids;
41			Halfedge_Mesh::HalfedgeRef new_he = ret.value()->halfedge;
42			Halfedge_Mesh::HalfedgeRef new_he_orig = new_he;
43			do {
44				new_vert_ids.insert(new_he->vertex->id);
45				new_he = new_he->next;
46			} while (new_he != new_he_orig);
47			if (vert_ids != new_vert_ids) {
48				throw Test::error("Erase edge did not return a face with correct vertices!");
49			}
50			// check for expected number of elements
51			if (numVerts != mesh.vertices.size()) {
52				throw Test::error("Erase edge should not create/delete a vertex!");
53			}
54			if (numEdges - 1 != mesh.edges.size()) {
55				throw Test::error("Erase edge did not erase an edge!");
56			}
57			if (numFaces - 1 != mesh.faces.size()) {
58				throw Test::error("Erase edge did not erase a face!");
59			}
60			// check mesh shape:
61	        if (auto diff = Test::differs(mesh, after)) {
62			    throw Test::error("Result does not match expected: " + diff.value());
63		    }
64		} else {
65			throw Test::error("Erase edge rejected operation!");
66		}
67	}
