6	static void expect_collapse(Halfedge_Mesh& mesh, Halfedge_Mesh::FaceRef face, Halfedge_Mesh const &after) {
7	
8		size_t numVerts = mesh.vertices.size();
9		size_t numEdges = mesh.edges.size();
10		size_t numFaces = mesh.faces.size();
11		size_t faceDeg = face->degree();
12	
13		if (auto ret = mesh.collapse_face(face)) {
14			if (auto msg = mesh.validate()) {
15				throw Test::error("Invalid mesh: " + msg.value().second);
16			}
17			// check for expected number of elements
18			if (numVerts - faceDeg + 1 != mesh.vertices.size()) {
19				throw Test::error("Some vertices were not erased!");
20			}
21			if (numEdges <= mesh.edges.size()) {
22				throw Test::error("Some edges were not erased!");
23			}
24			if (numFaces <= mesh.faces.size()) {
25				throw Test::error("Collapse face did not erase a face!");
26			}
27			// check mesh shape:
28	        if (auto diff = Test::differs(mesh, after)) {
29			    throw Test::error("Result does not match expected: " + diff.value());
30		    }
31		} else {
32			throw Test::error("Collapse face rejected operation!");
33		}
34	}
