7	static void expect_inset(Halfedge_Mesh& mesh, Halfedge_Mesh::FaceRef face, Halfedge_Mesh const &after) {
8	
9		size_t numVerts = mesh.vertices.size();
10		size_t numEdges = mesh.edges.size();
11		size_t numFaces = mesh.faces.size();
12	
13		std::set<uint32_t> vert_ids;
14		for (Halfedge_Mesh::VertexRef v = mesh.vertices.begin(); v != mesh.vertices.end(); v++) {
15			vert_ids.insert(v->id);
16		}
17	
18		uint32_t face_d = face->degree();
19	
20		if (auto ret = mesh.inset_vertex(face)) {
21			if (auto msg = mesh.validate()) {
22				throw Test::error("Invalid mesh: " + msg.value().second);
23			}
24			// check if returned vertex is a new vertex
25			if (vert_ids.find(face->id) != vert_ids.end()) {
26				throw Test::error("Inset vertex did not return a new vertex!");
27			}
28			// check for expected number of elements
29			if (numVerts + 1 != mesh.vertices.size()) {
30				throw Test::error("Inset vertex should create one vertex!");
31			}
32			if (numEdges + face_d != mesh.edges.size()) {
33				throw Test::error("Inset vertex didn't create the right number of new edges!");
34			}
35			if (numFaces + face_d - 1 != mesh.faces.size()) {
36				throw Test::error("Inset vertex didn't create the right number of new faces!");
37			}
