6	static void expect_bevel_vertex(Halfedge_Mesh& mesh, Halfedge_Mesh::VertexRef vertex, Vec3 dir, float dist, Halfedge_Mesh const &after) {
7		size_t numVerts = mesh.vertices.size();
8		size_t numEdges = mesh.edges.size();
9		size_t numFaces = mesh.faces.size();
10	
11		std::set<Vec3> old_verts;
12		old_verts.insert(vertex->position);
13	
14		std::set<uint32_t> face_ids;
15		for (Halfedge_Mesh::FaceRef f = mesh.faces.begin(); f != mesh.faces.end(); f++) {
16			face_ids.insert(f->id);
17		}
18	
19		size_t vertDeg = vertex->degree();
20	
21		// create a copy of vertice IDs incident to vertex to be bevelled
22		Halfedge_Mesh::HalfedgeRef he = vertex->halfedge;
23		Halfedge_Mesh::HalfedgeRef heOrig = he;
24		std::set<uint32_t> old_vert_connect;
25		do {
26			old_vert_connect.insert(he->twin->vertex->id);
27			he = he->twin->next;
28		} while (he != heOrig);
29	
30		if (auto ret = mesh.bevel_vertex(vertex)) {
31			Halfedge_Mesh::FaceRef face = ret.value();
32	        if (auto msg = mesh.validate()) {
33				throw Test::error("Invalid mesh: " + msg.value().second);
34			}
35	
36			// check if returned face is a new face
37			if (face_ids.find(face->id) != face_ids.end()) {
38				throw Test::error("Bevel vertex did not return a new face!");
39			}
40	
41			// check the number of new elements created
42			if (numVerts + vertDeg - 1 != mesh.vertices.size()) {
43				throw Test::error("Bevel vertex created incorrect number of vertices!");
44			}
45			if (numEdges + vertDeg != mesh.edges.size()) {
46				throw Test::error("Bevel vertex created incorrect number of edges!");
47			}
48			if (numFaces + 1 != mesh.faces.size()) {
49				throw Test::error("Bevel vertex created incorrect number of faces!");
50			}
51	
52			// extract the newly created vertices, check their positions are identical to input vertex's
53			std::set<Vec3> new_verts;
54			std::set<Halfedge_Mesh::VertexRef> new_vert_ref;
55			Halfedge_Mesh::HalfedgeRef face_he = face->halfedge;
56			Halfedge_Mesh::HalfedgeRef face_he_orig = face_he;
57	        std::vector<Vec3> start_positions;
58			do {
59	            start_positions.push_back(face_he->vertex->position);
60				new_verts.insert(face_he->vertex->position);
61				new_vert_ref.insert(face_he->vertex);
62				face_he = face_he->next;
63			} while (face_he != face_he_orig);
64	
65			if (old_verts != new_verts) {
66				throw Test::error("Bevel vertex created vertices at incorrect positions!");
67			}
68	
69			mesh.bevel_positions(face, start_positions, dir, dist);
70	
71			// check mesh shape:
72			if (auto difference = Test::differs(mesh, after, Test::CheckAllBits)) {
73				throw Test::error("Resulting mesh did not match expected: " + *difference);
74			}
75		} else {
76			throw Test::error("Bevel vertex rejected operation!");
77		}
78	}
